import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";import"./chunks/assets.CKUgKlCM.js";var i=JSON.parse(`{"title":"SysReptor Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"insights/architecture.md","filePath":"insights/architecture.md","lastUpdated":1781102819000}`),a={name:`insights/architecture.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /insights/architecture.md for this page in Markdown format</div><h1 id="sysreptor-architecture" tabindex="-1">SysReptor Architecture <a class="header-anchor" href="#sysreptor-architecture" aria-label="Permalink to “SysReptor Architecture”">​</a></h1><p>This is a short explanation of the SysReptor architecture in self-hosted environments.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p><img src="/images/architecture.png" alt="SysReptor self-hosted architecture" width="2038" height="1059"></p><h2 id="the-happy-sysreptor-user" tabindex="-1">The Happy SysReptor User <a class="header-anchor" href="#the-happy-sysreptor-user" aria-label="Permalink to “The Happy SysReptor User”">​</a></h2><p>The happy SysReptor user accesses SysReptor with a browser. The user is so happy because pentest reporting is now more convenient.</p><h2 id="the-web-browser" tabindex="-1">The Web Browser <a class="header-anchor" href="#the-web-browser" aria-label="Permalink to “The Web Browser”">​</a></h2><p>Web browser should be up to date. We officially support Chrome, Firefox, Safari and Edge. The browser displays the web contents and executes JavaScript and Vue.js code delivered from the SysReptor app.</p><p>Communications happens via the HTTP(S) protocol and via WebSockets.</p><h2 id="the-server" tabindex="-1">The Server <a class="header-anchor" href="#the-server" aria-label="Permalink to “The Server”">​</a></h2><p>An Ubunutu server with preinstalled Docker v2 incl. the Docker Compose plugin is a prerequisiste of running SysReptor.<br> It might be possible to use different Operating Systems or Distributions, which is, however, not officially supported.</p><h2 id="the-web-server" tabindex="-1">The Web Server <a class="header-anchor" href="#the-web-server" aria-label="Permalink to “The Web Server”">​</a></h2><p>The web server is responsible for handling web requests and for proxying the requests to the SysReptor App server.<br> We recommend setting up TLS for encrypted communication.</p><p>Our <a href="/setup/installation#easy-script-installation">setup script</a> offers the possibility to spin up a Caddy web server as reverse proxy, which also handles TLS certificates, incl. renewals. You can, however, also use reverse proxies that already exist in your infrastructure. They must be able to handle WebSocket communications.</p><h2 id="the-sysreptor-app" tabindex="-1">The SysReptor App <a class="header-anchor" href="#the-sysreptor-app" aria-label="Permalink to “The SysReptor App”">​</a></h2><p>This is our core component that we actively develop and maintain. It is a Python/Django application and uses the Django Rest Framework (DRF) as server technology, and Vue.js with Vuetify as client/frontend technology. The SysReptor app handles the application logic, permissions, data handling, etc. In self-hosted installations, it also does the PDF rendering jobs that <a href="/insights/rendering-workflow">render data to PDF</a>. For this, it uses a headless Chromium browser for rendering the final HTML and <a href="https://weasyprint.org/" target="_blank" rel="noreferrer">Weasyprint</a> for converting the HTML to PDF.</p><h2 id="the-database" tabindex="-1">The Database <a class="header-anchor" href="#the-database" aria-label="Permalink to “The Database”">​</a></h2><p>SysReptor uses a PostgreSQL database for storing data persistently. The SysReptor app optionally holds a secret which is used to store sensitive data in encrypted form.<br> If encryption is enabled, you must have the secret to be able to restore data from the database.</p><h2 id="redis" tabindex="-1">Redis <a class="header-anchor" href="#redis" aria-label="Permalink to “Redis”">​</a></h2><p>SysReptor uses the in-memory database Redis for temporarily storing information. This is (among others) necessary for synchronizing activities between users during report writing, allowing for example collaborative editing.<br> Data stored in Redis is mostly indexes and references and is not encypted.</p><h2 id="languagetool" tabindex="-1">Languagetool <a class="header-anchor" href="#languagetool" aria-label="Permalink to “Languagetool”">​</a></h2><p>SysReptor Professional users can use the integrated spell check. This requires the <a href="https://languagetool.org/" target="_blank" rel="noreferrer">languagetool</a> container which provides a web API to receive text and to suggest improvements. Data received by languagetool in unencrypted and stored in memory and/or local caches.</p><h2 id="the-s3-bucket" tabindex="-1">The S3 Bucket <a class="header-anchor" href="#the-s3-bucket" aria-label="Permalink to “The S3 Bucket”">​</a></h2><p>Users can upload images to reports and any filetypes to notes. Those files are by default stored in the SysReptor app container. If encryption is enabled, all files are encrypted.</p><p>You can optionally configure SysReptor to use an S3 bucket for storing files. If encryption is enabled, the S3 bucket provider has no access to file contents. (When enabling encryption you must run <code>docker compose run --rm app python3 manage.py encryptdata</code> from the <code>deploy</code> directory to force encryption of stored but unencrypted data.)<br> You must have the secret to recover encrypted files from your S3 bucket.</p><h2 id="what-about-the-cloud" tabindex="-1">What about the Cloud? <a class="header-anchor" href="#what-about-the-cloud" aria-label="Permalink to “What about the Cloud?”">​</a></h2><p>This was an overview of the self-hosted SysReptor architecture. In our Cloud service, we use the same components, but maintain them in a Kubernetes cluster in which every customer receives a dedicated namespaces.</p><p>The database server is shared among the customers, but separated using dedicated users and databases for each customer.<br> Files are stored on an internal hosted S3 bucket. The SysReptor apps can only access their own files using temporary S3 keys with permissions restricted to their customer files.<br> PDF rendering is performed by a pool of rendering workers. The rendering worker pool is shared among all customers, but after each PDF render the worker job is shut down and replaced with a fresh worker instance. Rendering worker instances are never reused to render reports of different customers.</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};